1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface Item {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const HIGH_ENCHANTMENT_THRESHOLD = 5;
34	
35	const isCursed = (item: Item): boolean => item.cursed === true;
36	const isHighlyEnchanted = (item: Item): boolean =>
37	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
38	
39	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
40	  { applies: isCursed, rate: 0.5 },
41	  { applies: isHighlyEnchanted, rate: 0.3 },
42	];
43	
44	const itemSurcharge = (item: Item): number => {
45	  const applicableRates = SURCHARGE_RATES.filter(({ applies }) => applies(item));
46	  return basePremiumOf(item.type) * sumBy(applicableRates, ({ rate }) => rate);
47	};
48	
49	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
50	
51	interface QuoteStep {
52	  op: "quote";
53	  items: Item[];
54	}
55	
56	interface Damage {
57	  itemType: string;
58	  amount: number;
59	}
60	
61	interface ClaimStep {
62	  op: "claim";
63	  policy: number;
64	  incident: {
65	    cause: string;
66	    damages: Damage[];
67	  };
68	}
69	
70	type Step = QuoteStep | ClaimStep;
71	
72	interface Customer {
73	  yearsWithMHPCO: number;
74	}
75	
76	interface Scenario {
77	  customer: Customer;
78	  steps: Step[];
79	}
80	
81	interface QuoteResult {
82	  premium: number;
83	}
84	
85	interface ClaimResult {
86	  payout: number;
87	  remainingCap: number;
88	}
89	
90	type StepResult = QuoteResult | ClaimResult;
91	
92	interface ScenarioResult {
93	  results: StepResult[];
94	}
95	
96	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
97	const COMPONENT_BLOCK_SIZE = 3;
98	const COMPONENT_BLOCK_BASE = 60;
99	
100	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
101	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
102	
103	const groupCountsByType = (items: Item[]): Map<string, number> => {
104	  const counts = new Map<string, number>();
105	  for (const item of items) {
106	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
107	  }
108	  return counts;
109	};
110	
111	const typeBasePremium = (type: string, count: number): number => {
112	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
113	    return COMPONENT_BLOCK_BASE;
114	  }
115	  return basePremiumOf(type) * count;
116	};
117	
118	const itemsBasePremium = (items: Item[]): number =>
119	  sumBy([...groupCountsByType(items)], ([type, count]) => typeBasePremium(type, count));
120	
121	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
122	
123	const LOYALTY_YEARS_THRESHOLD = 2;
124	const LOYALTY_DISCOUNT_RATE = 0.2;
125	
126	const isLoyalCustomer = (customer: Customer): boolean =>
127	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
128	
129	const loyaltyDiscount = (customer: Customer, base: number): number =>
130	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
131	
132	const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
133	  const base = itemsBasePremium(items);
134	  const premiumBeforeFee =
135	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base);
136	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
137	};
