139	interface Policy {
140	  items: Item[];
141	  remainingCap: number;
142	}
143	
144	const itemInsuranceValue = (item: Item): number => insuranceValueOf(item.type);
145	
146	const createPolicy = (step: QuoteStep): Policy => ({
147	  items: step.items,
148	  remainingCap: sumBy(step.items, itemInsuranceValue) * CAP_MULTIPLIER,
149	});
150	
151	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
152	const FULL_REIMBURSEMENT_RATE = 1;
153	
154	const reimbursementRate = (item: Item): number =>
155	  isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
156	
157	const damagePayout = (damage: Damage, item: Item): number =>
158	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
159	
160	const findItem = (policy: Policy, itemType: string): Item =>
161	  policy.items.find((i) => i.type === itemType)!;
162	
163	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
164	  const policy = policies.get(step.policy)!;
165	  const rawPayout = sumBy(step.incident.damages, (d) =>
166	    damagePayout(d, findItem(policy, d.itemType)),
167	  );
168	  const payout = roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
169	  policy.remainingCap -= payout;
170	  return { payout, remainingCap: policy.remainingCap };
171	};
