173	export const runScenario = (scenario: Scenario): ScenarioResult => {
174	  const policies = new Map<number, Policy>();
175	  const results: StepResult[] = scenario.steps.map((step, index) => {
176	    if (step.op === "quote") {
177	      policies.set(index, createPolicy(step));
178	      return { premium: quotePremium(step, scenario.customer) };
179	    }
180	    return processClaim(step, policies);
181	  });
182	  return { results };
183	};
